// v222: how a look turns into parts and sheet bands (data/people.js), and that every look in the game names parts the
// sheet has (src/data/personSheet.js, generated by tools/sprites/person.py).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { lookOf, personLayers, personParts, HAIR_STYLES, BEARDS, OUTFITS, EXTRAS, GEAR } from '../src/data/people.js';
import { PERSON } from '../src/data/personSheet.js';
import { NPCS } from '../src/data/npcs.js';
import { CLOTHES } from '../src/data/clothing.js';
import { ITEMS } from '../src/data/items.js';

test('old looks keep their hair and beard', () => {
  assert.equal(lookOf({ long: true }).hair, 'long');
  assert.equal(lookOf({}).hair, 'short');
  assert.equal(lookOf({ beard: true }).beard, 'full');
  assert.equal(lookOf({ beard: false }).beard, null);
  assert.equal(lookOf({ hat: '#fff' }).hat, 'straw');   // a hat without a shape was always the straw hat
});

test('a style the sheet does not have falls back instead of drawing nothing', () => {
  const L = lookOf({ hairStyle: 'mohawk', beard: 'braids', outfit: 'armour', hat: '#fff', hatStyle: 'crown' });
  assert.deepEqual(L, { body: 'adult', hair: 'short', beard: null, outfit: null, extras: [], gear: null, hat: 'straw' });
});

test('under a hat the hair is the trimmed version, and the hat is drawn last', () => {
  const bands = personLayers({ skin: '#fff', hair: '#000', shirt: '#f00', pants: '#00f', hat: '#0f0', band: '#ff0', hatStyle: 'top' }).map(([b]) => b);
  assert.ok(bands.includes('hair:short@hat|hair'));
  assert.ok(!bands.includes('hair:short|hair'));
  assert.equal(bands[0], 'body|skin');
  assert.ok(bands.at(-1).startsWith('hat:top|'));
});

test('every layer a look draws is on the sheet and tinted to a colour', () => {
  const p = { skin: '#fff', hair: '#000', shirt: '#f00', pants: '#00f', hairStyle: 'bun', beard: 'goatee', outfit: 'apron', glasses: true, hat: '#0f0', hatStyle: 'beanie' };
  for (const [band, col] of personLayers(p)) {
    assert.ok(PERSON.layers.includes(band), band);
    if (!band.endsWith('|ink')) assert.ok(col, `${band} has a colour`);
  }
});

test('every labelled style is drawn on the sheet, and every drawn style is labelled', () => {
  assert.deepEqual(Object.keys(HAIR_STYLES).sort(), [...PERSON.styles.hair].sort());
  assert.deepEqual(Object.keys(BEARDS).sort(), [...PERSON.styles.beard].sort());
  assert.deepEqual(Object.keys(OUTFITS).sort(), [...PERSON.styles.outfit].sort());
  assert.deepEqual(Object.keys(EXTRAS).sort(), [...PERSON.styles.extra].sort());
  assert.deepEqual(Object.keys(GEAR).sort(), [...PERSON.styles.gear].sort());
});

test('every neighbour and every hat in the game uses styles the sheet has', () => {
  for (const n of NPCS) {
    const p = n.pal, L = lookOf(p);
    if (p.hairStyle) assert.equal(L.hair, p.hairStyle, n.id);
    if (p.outfit) assert.equal(L.outfit, p.outfit, n.id);
    if (typeof p.beard === 'string') assert.equal(L.beard, p.beard, n.id);
  }
  for (const [k, c] of Object.entries(CLOTHES)) if (c.slot === 'hat') assert.ok(PERSON.styles.hat.includes(c.style), k);
});

// v223: children have their own body; the head's parts are the adult ones, drawn lower.
test('a child has a child\'s body, keeps hair, glasses and hat, and wears no beard or outfit', () => {
  const p = { small: true, skin: '#fff', hair: '#000', shirt: '#f00', pants: '#00f', hairStyle: 'bun', beard: 'full', outfit: 'apron', glasses: true, hat: '#0f0', hatStyle: 'cap' };
  const L = lookOf(p), P = personParts(p);
  assert.deepEqual([L.body, L.hair, L.beard, L.outfit, L.extras, L.hat], ['child', 'bun', null, null, ['glasses'], 'cap']);
  assert.ok(P.body.every(([b]) => b.startsWith('body:child|')));
  assert.ok(P.head.some(([b]) => b === 'hair:bun@hat|hair') && P.head.some(([b]) => b.startsWith('hat:cap|')));
  assert.ok(P.dy > 0 && P.bob === false);
  for (const [b] of [...P.body, ...P.head]) assert.ok(PERSON.layers.includes(b), b);
});

test('an adult draws everything in one piece, at the sheet\'s own height', () => {
  const P = personParts({ skin: '#fff', hair: '#000', shirt: '#f00', pants: '#00f' });
  assert.equal(P.dy, 0);
  assert.equal(P.body[0][0], 'body|skin');
});

test('Pip is drawn as a child', () => {
  assert.equal(lookOf(NPCS.find((n) => n.id === 'pip').pal).body, 'child');
});

// v224: scarves, satchels and cardigans.
test('a scarf and a satchel are drawn in their own colours, the scarf under the glasses', () => {
  const p = { skin: '#fff', hair: '#000', shirt: '#f00', pants: '#00f', scarf: '#123456', bag: '#654321', glasses: true };
  const bands = personLayers(p), at = (b) => bands.findIndex(([k]) => k === b);
  assert.deepEqual(bands.find(([k]) => k === 'extra:scarf|scarf'), ['extra:scarf|scarf', '#123456']);
  assert.deepEqual(bands.find(([k]) => k === 'gear:bag|bag'), ['gear:bag|bag', '#654321']);
  assert.ok(at('extra:scarf|scarf') < at('extra:glasses|ink'));
});

test('a child keeps a scarf but carries no satchel', () => {
  const L = lookOf({ small: true, scarf: '#123456', bag: '#654321' });
  assert.deepEqual(L.extras, ['scarf']);
  assert.equal(L.gear, null);
});

test('the cardigan is a shirt you tailor from wool, worn over your own shirt', () => {
  const c = CLOTHES.cardigan;
  assert.equal(c.slot, 'shirt');
  assert.ok(ITEMS[c.from], 'wool is an item');
  assert.ok(PERSON.styles.outfit.includes(c.style));
  assert.equal(Object.values(CLOTHES).filter((k) => k.from === c.from).length, 1, 'one piece per item');
});
